:root{
  /* update css variables starts here */
  /* Typography - Font Sizes */
  --text-xxs: 10px;
  --text-xs: 11px;
  --text-sm: 12px;
  --text-base: 13px;
  --text-md: 14px;
  --text-lg: 15px;
  --text-xl: 16px;
  --text-2xl: 18px;
  --text-3xl: 20px;
  --text-4xl: 22px;
  --text-5xl: 24px;
  --text-6xl: 25px;
  --text-7xl: 30px;
  --text-8xl: 35px;
  --text-9xl: 40px;
  --text-10xl: 60px;
  --text-11xl: 74px;

  /* Typography - Font Weight */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 12px;
  --spacing-lg: 16px;
  --spacing-xl: 20px;
  --spacing-2xl: 32px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 25px;

  /* line height */
  --line-height-normal: 1.2em;
  --line-height-medium: 1.4em;
  --line-height-large: 1.6em;
  /* update css variables ends here */

  --color-white: #ffffff;
  --color-black: #000000;

  --font-11: 11px;
  --font-12: 12px;
  --base-font-family: 'Inter', sans-serif;
}

:root,
:root.light {
  --font-13: 13px;
